import json,re
d=json.load(open('sheets.json'))
out=[]
def walk(n, depth=0):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text' and 'text' in n:
            out.append(n['text'])
        if t=='heading':
            out.append('\n## '+n.get('text','')+'\n')
        if t=='paragraph':
            out.append('\nPARA:')
        if t=='listItem':
            out.append('\n- ')
        if t=='codeVoice':
            out.append('\`'+n.get('code','')+'\`')
        for k,v in n.items():
            if k not in ('text','code'):
                walk(v,depth+1)
    elif isinstance(n,list):
        for i in n: walk(i,depth)
walk(d.get('primaryContentSections',[]))
walk(d.get('abstract',[]))
print(''.join(out))
